# Original procedural audio for Kindred Lights (all generated by this script).
import numpy as np, wave
SR=44100; BPM=80; BEAT=60/BPM; BAR=4*BEAT; LOOP=8*BAR  # 24 s
def mtof(m): return 440*2**((m-69)/12)
def save(name,x):
    x=np.asarray(x); 
    if x.ndim==1: x=np.stack([x,x],1)
    x=x/ (np.abs(x).max()+1e-9)*0.89
    w=wave.open(f'game/audio/{name}.wav','wb'); w.setnchannels(2); w.setsampwidth(2); w.setframerate(SR)
    w.writeframes((x*32767).astype('<i2').tobytes()); w.close()
def env(n,a,r):
    e=np.ones(n); A=int(a*SR); R=int(r*SR)
    if A: e[:A]=np.linspace(0,1,A)
    if R: e[-R:]*=np.linspace(1,0,R)**2
    return e
def tone(f,dur,harm=(1,.3,.1),det=0.0,decay=None):
    t=np.arange(int(dur*SR))/SR; y=np.zeros_like(t)
    for i,a in enumerate(harm):
        for d in ((-det,det) if det else (0,)):
            y+=a*np.sin(2*np.pi*f*(i+1)*(1+d)*t+np.random.rand()*6)
    if decay: y*=np.exp(-t/decay)
    return y
def place(buf,y,t0,pan=0.0):
    i=int(t0*SR); n=len(buf)
    L=np.cos((pan+1)*np.pi/4); R=np.sin((pan+1)*np.pi/4)
    idx=(np.arange(len(y))+i)%n  # wrap -> seamless loop
    np.add.at(buf[:,0],idx,y*L); np.add.at(buf[:,1],idx,y*R)
def lowpass(x,a):
    y=np.zeros_like(x); s=0
    for i in range(len(x)): s+=a*(x[i]-s); y[i]=s
    return y
def reverb(st,mix=.35):
    out=st.copy()
    for d,g in ((0.031,.5),(0.047,.45),(0.071,.4),(0.113,.35),(0.163,.3),(0.241,.25),(0.337,.2)):
        k=int(d*SR); out[:,0]+=g*mix*np.roll(st[:,1],k); out[:,1]+=g*mix*np.roll(st[:,0],k)
    return out
np.random.seed(7)
N=int(LOOP*SR)
# chords: Fm, Db, Ab, Eb  (2 bars each)
CH=[[53,56,60],[49,53,56],[56,60,63],[51,55,58]]
ROOT=[41,37,44,39]
# L0 drone
b=np.zeros((N,2))
for k in range(4):
    y=tone(mtof(ROOT[k]),2*BAR+1.5,(1,.5,.2,.08),det=.002)*env(int((2*BAR+1.5)*SR),1.2,1.6)
    place(b,y*.8,k*2*BAR)
save('layer0',reverb(b))
# L1 pad
b=np.zeros((N,2))
for k in range(4):
    for j,m in enumerate(CH[k]):
        y=tone(mtof(m+12),2*BAR+1.5,(1,.25,.12,.05),det=.003)*env(int((2*BAR+1.5)*SR),1.5,1.8)
        place(b,y*.35,k*2*BAR,pan=(j-1)*.5)
save('layer1',reverb(b,.5))
# L2 arpeggio plucks, eighth notes
b=np.zeros((N,2))
for k in range(4):
    notes=CH[k]+[CH[k][0]+12]
    pat=[0,1,2,3,2,1,2,3]
    for bar in range(2):
        for e in range(8):
            m=notes[pat[e]]+12
            y=tone(mtof(m),1.6,(1,.4,.15,.08),decay=.35)*env(int(1.6*SR),.004,.2)
            place(b,y*(.5 if e%2 else .65),k*2*BAR+bar*BAR+e*BEAT/2,pan=np.sin(e)*.6)
save('layer2',reverb(b,.55))
# L3 bell melody (sparse, F minor pentatonic)
b=np.zeros((N,2))
mel=[(0,72),(1.5,75),(3,77),(6,80),(8,77),(9.5,75),(11,72),(14,68),(16,72),(17.5,75),(19,79),(22,77)]
for t0,m in mel:
    y=(tone(mtof(m),3.5,(1,0,.25,0,.1),decay=1.1)+.3*tone(mtof(m)*2.76,3.5,(1,),decay=.4))*env(int(3.5*SR),.003,.5)
    place(b,y*.5,t0,pan=np.random.uniform(-.7,.7))
save('layer3',reverb(b,.7))
# chime (F5) for joins, pitched in game
t=3.0; y=(tone(mtof(77),t,(1,0,.2,0,.08),decay=.9)+.25*tone(mtof(77)*3.01,t,(1,),decay=.3))*env(int(t*SR),.002,.6)
st=np.stack([y,y],1); save('chime',reverb(st,.6))
# hum loop: soft voice-like tone, 2 s, loopable (integer cycles of 174.6Hz approx -> choose f=175)
t=np.arange(int(2*SR))/SR; f=175.0
vib=np.sin(2*np.pi*2.5*t)*0.004
ph=2*np.pi*f*np.cumsum(1+vib)/SR
y=sum(a*np.sin((i+1)*ph) for i,a in enumerate((1,.55,.35,.2,.12,.06)))
save('hum',np.stack([y,y],1))
# beacon swell: Fm add9 chord
t=6.0; n=int(t*SR); st=np.zeros((n,2))
for j,m in enumerate([53,60,65,68,72,79]):
    y=tone(mtof(m),t,(1,.3,.1),det=.003)*env(n,.08,3.5)*np.exp(-np.arange(n)/SR/2.5)
    p=(j/5-.5)*1.2; st[:,0]+=y*np.cos((p+1)*np.pi/4); st[:,1]+=y*np.sin((p+1)*np.pi/4)
for m in [77,80,84,89]:
    y=tone(mtof(m),t,(1,0,.2),decay=.8)*env(n,.002,1)
    st+=np.stack([y,y],1)*.3
save('beacon',reverb(st,.6))
# scatter: descending soft gliss
t=1.6; tt=np.arange(int(t*SR))/SR; f=np.geomspace(700,180,len(tt))
y=np.sin(2*np.pi*np.cumsum(f)/SR)*np.exp(-tt/.6)*env(len(tt),.01,.3)
save('scatter',reverb(np.stack([y,y],1),.5))
# wind loop 8 s (filtered noise, seamless by crossfade)
n=int(8*SR); m=int(1*SR); w=np.random.randn(n+m)
w=lowpass(lowpass(w,.03),.05); w[:m]=w[:m]*np.linspace(0,1,m)+w[n:]*np.linspace(1,0,m); w=w[:n]
w*= .7+.3*np.sin(2*np.pi*np.arange(n)/n*2)
w2=np.roll(w,int(.4*SR)); save('wind',np.stack([w,w2],1))
print('ok')
